'use strict';

// MODULES //

var HALF_PI = require( '@stdlib/constants-float32-half-pi' );
var PI = require( '@stdlib/constants-float32-pi' );
var isnanf = require( '@stdlib/math-base-assert-is-nanf' );
var absf = require( '@stdlib/math-base-special-absf' );
var sincosf = require( '@stdlib/math-base-special-sincosf' ).assign;
var f32 = require( '@stdlib/number-float64-base-to-float32' );
var polyC = require( './polyval_cn.js' );
var polyF = require( './polyval_fn.js' );
var polyG = require( './polyval_gn.js' );
var polyS = require( './polyval_sn.js' );


// VARIABLES //

// Array for storing sincos evaluation:
var sc = [ 0.0, 0.0 ];


// MAIN //

/**
* Computes the Fresnel integrals S(x) and C(x) for a single-precision floating-point number and assigns results to a provided output array.
*
* ## Method
*
* Evaluates the Fresnel integrals
*
* ```tex
* \begin{align*}
* \operatorname{S}(x) &= \int_0^x \sin\left(\frac{\pi}{2} t^2\right)\,\mathrm{d}t, \\
* \operatorname{C}(x) &= \int_0^x \cos\left(\frac{\pi}{2} t^2\right)\,\mathrm{d}t.
* \end{align*}
* ```
*
* The integrals are evaluated by a power series for small \\( x \\). For larger \\( x \\), auxiliary functions \\( f(x) \\) and \\( g(x) \\) are employed such that
*
* ```tex
* \begin{align*}
* \operatorname{C}(x) &= \frac{1}{2} + f(x) \sin\left( \frac{\pi}{2} x^2 \right) - g(x) \cos\left( \frac{\pi}{2} x^2 \right), \\
* \operatorname{S}(x) &= \frac{1}{2} - f(x) \cos\left( \frac{\pi}{2} x^2 \right) - g(x) \sin\left( \frac{\pi}{2} x^2 \right).
* \end{align*}
* ```
*
* ## Notes
*
* -   Relative error on test interval \\( \[0,10\] \\):
*
*     | arithmetic | function | # trials | peak    | rms     |
*     |:----------:|:--------:|:--------:|:-------:|:-------:|
*     | IEEE       | S(x)     | 30000    | 1.1e-6  | 1.9e-7  |
*     | IEEE       | C(x)     | 30000    | 1.1e-6  | 2.0e-7  |
*
* @param {number} x - input value
* @param {Collection} out - output array
* @param {integer} stride - output array stride
* @param {NonNegativeInteger} offset - output array index offset
* @returns {Collection} output array
*
* @example
* var v = fresnelf( 0.0, [ 0.0, 0.0 ], 1, 0 );
* // returns [ 0.0, 0.0 ]
*
* @example
* var v = fresnelf( 1.0, [ 0.0, 0.0 ], 1, 0 );
* // returns [ ~0.438, ~0.780 ]
*
* @example
* var v = fresnelf( Infinity, [ 0.0, 0.0 ], 1, 0 );
* // returns [ ~0.5, ~0.5 ]
*
* @example
* var v = fresnelf( -Infinity, [ 0.0, 0.0 ], 1, 0 );
* // returns [ ~-0.5, ~-0.5 ]
*
* @example
* var v = fresnelf( NaN, [ 0.0, 0.0 ], 1, 0 );
* // returns [ NaN, NaN ]
*/
function fresnelf( x, out, stride, offset ) {
	var x2;
	var xa;
	var f;
	var g;
	var t;
	var u;

	// Special case: NaN
	if ( isnanf( x ) ) {
		out[ offset ] = NaN;
		out[ offset + stride ] = NaN;
		return out;
	}
	x = f32( x );
	xa = absf( x );
	x2 = f32( xa * xa );

	if ( x2 < 2.5625 ) {
		t = f32( x2 * x2 );
		out[ offset ] = f32( f32( xa * x2 ) * polyS( t ) );
		out[ offset + stride ] = f32( xa * polyC( t ) );
	} else if ( xa > 36974.0 ) {
		out[ offset ] = 0.5;
		out[ offset + stride ] = 0.5;
	} else {
		// Asymptotic power series auxiliary functions for large arguments...
		t = f32( PI * x2 );
		u = f32( 1.0 / f32( t * t ) );
		t = f32( 1.0 / t );
		f = f32( 1.0 - f32( u * polyF( u ) ) );
		g = f32( t * polyG( u ) );
		t = f32( HALF_PI * x2 );
		sincosf( t, sc, 1, 0 );
		t = f32( PI * xa );
		out[ offset + stride ] = f32( 0.5 + f32( f32( f32( f * sc[0] ) - f32( g * sc[1] ) ) / t ) ); // eslint-disable-line max-len
		out[ offset ] = f32( 0.5 - f32( f32( f32( f * sc[1] ) + f32( g * sc[0] ) ) / t ) ); // eslint-disable-line max-len
	}
	if ( x < 0.0 ) {
		out[ offset ] = -out[ offset ];
		out[ offset + stride ] = -out[ offset + stride ];
	}
	return out;
}


// EXPORTS //

module.exports = fresnelf;
