'use strict';

/**
* Compute the Fresnel integrals S(x) and C(x) for a single-precision floating-point number.
*
* @module @stdlib/math-base-special-fresnelf
*
* @example
* var fresnelf = require( '@stdlib/math-base-special-fresnelf' );
*
* var v = fresnelf( 0.0 );
* // returns <Float32Array>[ 0.0, 0.0 ]
*
* v = fresnelf( 1.0 );
* // returns <Float32Array>[ ~0.438, ~0.780 ]
*
* v = fresnelf( Infinity );
* // returns <Float32Array>[ ~0.5, ~0.5 ]
*
* v = fresnelf( -Infinity );
* // returns <Float32Array>[ ~-0.5, ~-0.5 ]
*
* v = fresnelf( NaN );
* // returns <Float32Array>[ NaN, NaN ]
*
* @example
* var Float32Array = require( '@stdlib/array-float32' );
* var fresnelf = require( '@stdlib/math-base-special-fresnelf' );
*
* var out = new Float32Array( 2 );
*
* var v = fresnelf.assign( 0.0, out, 1, 0 );
* // returns <Float32Array>[ ~0.0, ~0.0 ]
*
* var bool = ( v === out );
* // returns true
*/

// MODULES //

var setReadOnly = require( '@stdlib/utils-define-nonenumerable-read-only-property' );
var main = require( './main.js' );
var assign = require( './assign.js' );


// MAIN //

setReadOnly( main, 'assign', assign );


// EXPORTS //

module.exports = main;
