'use strict';

// MODULES //

var Float32Array = require( '@stdlib/array-float32' );
var assign = require( './assign.js' );


// MAIN //

/**
* Computes the Fresnel integrals S(x) and C(x) for a single-precision floating-point number.
*
* @param {number} x - input value
* @returns {Float32Array} S(x) and C(x)
*
* @example
* var v = fresnelf( 0.0 );
* // returns <Float32Array>[ 0.0, 0.0 ]
*
* @example
* var v = fresnelf( 1.0 );
* // returns <Float32Array>[ ~0.438, ~0.780 ]
*
* @example
* var v = fresnelf( Infinity );
* // returns <Float32Array>[ ~0.5, ~0.5 ]
*
* @example
* var v = fresnelf( -Infinity );
* // returns <Float32Array>[ ~-0.5, ~-0.5 ]
*
* @example
* var v = fresnelf( NaN );
* // returns <Float32Array>[ NaN, NaN ]
*/
function fresnelf( x ) {
	return assign( x, new Float32Array( 2 ), 1, 0 );
}


// EXPORTS //

module.exports = fresnelf;
